"""Read-only BCC lookup: no card data, keys, personal data or financial commands."""
import json,subprocess
from pathlib import Path
root=Path('/opt/joba/current').resolve()
source=r"""const {Client}=require('pg'),crypto=require('node:crypto'),{loadBccConfig,BccGateway,bccOrder}=require('/app/services/api/dist/bcc-gateway');
(async()=>{const db=new Client({connectionString:process.env.DATABASE_URL});await db.connect();try{await db.query('BEGIN READ ONLY');const c=loadBccConfig();if(!c)throw Error('Unavailable');const bank=new BccGateway(c,{});const rows=(await db.query("SELECT data FROM records WHERE kind='bank_checkout' AND data->>'provider'='bcc' AND data->>'environment'=$1 ORDER BY data->>'created_at' DESC LIMIT 8",[c.environment])).rows;const payments=[];for(const {data:p}of rows){const item={id:p.id,owner_tag:crypto.createHash('sha256').update(p.owner).digest('hex').slice(0,12),order_matches_report:bccOrder(p.id)==='10917286642734770830851119657',created_at:p.created_at,status:p.status,cancel_requested:p.cancel_requested===true,form_opened:!!p.form_opened_at,expires_at:p.expires_at,last_error:p.last_error,amount_minor:p.amount_minor,currency:p.currency};try{const r=await bank.status({orderId:p.bank_order_id||bccOrder(p.id)});item.bank={ACTION:r.ACTION,RC:r.RC,order_matches:String(r.ORDER)===bccOrder(p.id),terminal_matches:String(r.TERMINAL)===c.terminal,amount_present:r.AMOUNT!==undefined,currency_present:r.CURRENCY!==undefined};}catch{item.bank={unavailable:true};}payments.push(item);}await db.query('ROLLBACK');console.log(JSON.stringify({checked_at:new Date().toISOString(),environment:c.environment,payments,read_only:true,financial_commands:false}));}finally{await db.end();}})().catch(()=>{console.error('Read-only BCC diagnosis failed; private details omitted');process.exitCode=1});"""
cmd=['docker','compose','--env-file','/etc/joba/production.env','-f',str(root/'infra/production/compose.yaml'),'exec','-T','api','node','-e',source]
r=subprocess.run(cmd,capture_output=True,text=True,timeout=200)
if r.returncode:raise SystemExit('Read-only BCC diagnosis failed; no private details logged')
print(json.dumps(json.loads(r.stdout)))
